def do_algebra(operator, operand):
    # Check if the lengths are correct
    assert len(operator) == len(operand) - 1

    # Initialize variables to store intermediate results
    result = operand[0]
    i = 0

    # Loop through each operator and operand pair
    for op in operator:
        # Apply the operation based on the operator
        if op == '+':
            result += operand[i + 1]
        elif op == '-':
            result -= operand[i + 1]
        elif op == '*':
            result *= operand[i + 1]
        elif op == '//':
            result //= operand[i + 1]
        else:
            # For exponentiation, use the ** operator
            if i > 0 and op == '**':
                result = pow(result, operand[i + 1])
            else:
                raise ValueError(f"Unsupported operation: {op}")

        # Move to the next element in the operand list
        i += 1

    return result
```

