def solve(s):
    # Check if the string contains any letters
    has_letters = False
    for char in s:
        if char.isalpha():
            has_letters = True
            break

    # If no letters, reverse the entire string
    if not has_letters:
        return s[::-1]

    # Otherwise, reverse the case of each letter
    result = ""
    for char in s:
        if char.isalpha():
            if char.islower():
                result += char.upper()
            else:
                result += char.lower()
        else:
            result += char

    return result

